def smallest_change(arr):
    def is_palindrome(sub_arr):
        return sub_arr == sub_arr[::-1]

    def min_changes(sub_arr):
        changes = 0
        left, right = 0, len(sub_arr) - 1
        while left < right:
            if sub_arr[left] != sub_arr[right]:
                changes += 1
            left += 1
            right -= 1
        return changes

    min_changes_needed = float('inf')
    for i in range(len(arr)):
        for j in range(i, len(arr)):
            sub_arr = arr[i:j+1]
            changes_needed = min_changes(sub_arr)
            if is_palindrome(sub_arr) and changes_needed < min_changes_needed:
                min_changes_needed = changes_needed

    return min_changes_needed

