    if not has_no_more_than_three_digits(file_name):
        return 'No'

    if not contains_exactly_one_dot(file_name):
        return 'No'

    name, extension = file_name.split('.')

    if not starts_with_letter(name):
        return 'No'

    if not is_valid_extension(extension):
        return 'No'

    return 'Yes'

