def find_min_element(arr):
    left, right = 0, len(arr) - 1

    while left < right:
        mid = left + (right - left) // 2

        if arr[mid] > arr[right]:
            left = mid + 1
        else:
            right = mid

    return arr[left]

def calculate_right_shifts(arr):
    pivot = arr[0]
    if pivot <= arr[-1]:
        return 0

    min_element = find_min_element(arr)
    return len(arr) - arr.index(min_element)

