from typing import List, Tuple

def find_closest_elements(numbers: List[float]) -> Tuple[float, float]:
    if len(numbers) < 2:
        raise ValueError("Input list must have at least two elements.")

    unique_numbers = list(set(numbers))
    if len(unique_numbers) < 2:
        raise ValueError("Input list must have at least two distinct values.")

    differences = [(abs(numbers[i] - numbers[j]), numbers[i], numbers[j]) for i in range(len(numbers)) for j in range(i+1, len(numbers))]
    closest_elements = min(differences, key=lambda x: x[0])[1:]

    return tuple(sorted(closest_elements))

