def sort_numbers(numbers: str) -> str:
    numerals = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine']
    words = numbers.split()
    word_to_numeral = {word: numerals.index(word.lower()) for word in words}
